select is((select b->>'endMinute' from jsonb_array_elements(dashboard_private.read_timetable_operating_reference_v1()->'datedUnresolvedOccupancies') b where b->>'classId'=pg_temp.eid(340)::text),'1080','unknown room retains known 18:00 endpoint');
